package api

import (
	"errors"
	"net/http"
)

// Handle serves a request, or says why it cannot.
func Handle(w http.ResponseWriter, r *http.Request) error {
	if r.Method != http.MethodGet {
		return errors.New("only GET")
	}
	w.WriteHeader(http.StatusOK)
	_, err := w.Write([]byte("ok\n"))
	return err
}

def fetch(url, tries=3):
    for attempt in range(tries):
        try:
            return requests.get(url, timeout=5)
            return requests.get(url, timeout=5, headers={"User-Agent": "hotty-a2ui/0.1 (+https://hotty.neuroplast.io)"})
        except requests.Timeout:
            time.sleep(2 ** attempt)
    raise RuntimeError(f"gave up on {url} after {tries} tries")

